<?php include 'config.php'; if(!isLoggedIn()){header('Location: login.php');exit;} $uid=$_SESSION['user_id']; $items=$conn->query("SELECT ci.*,p.name,p.price,p.image_url FROM cart_items ci JOIN products p ON ci.product_id=p.product_id WHERE ci.user_id=$uid"); $total=0; ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Cart</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><section class="page"><h1 class="section-title">Cart</h1><div class="table-box"><table><tr><th>Image</th><th>Name</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr><?php while($i=$items->fetch_assoc()): $line=$i['price']*$i['quantity']; $total+=$line; ?><tr><td><img class="cart-img" src="<?=clean($i['image_url'])?>"></td><td><?=clean($i['name'])?></td><td>$<?=$i['price']?></td><td><form method="POST" action="update_cart.php"><input type="hidden" name="cart_id" value="<?=$i['cart_id']?>"><input name="quantity" type="number" value="<?=$i['quantity']?>" min="1" style="width:70px"><button>Update</button></form></td><td>$<?=number_format($line,2)?></td><td><a class="btn" href="remove_from_cart.php?id=<?=$i['cart_id']?>">Remove</a></td></tr><?php endwhile; ?></table><h2>Total: $<?=number_format($total,2)?></h2><a class="btn" href="checkout.php">Checkout</a></div></section></body></html>